from __future__ import annotations


PROJECT_HTML = r'''<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="pe-csrf" content="__CSRF_TOKEN__"><title>DILIVOX — Управление проектом</title>
<style>
:root{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:#f4f4f6;color:#171719}*{box-sizing:border-box}body{margin:0}.wrap{max-width:1420px;margin:auto;padding:24px}.top{display:flex;justify-content:space-between;gap:18px;align-items:flex-start}.eyebrow{font-size:12px;letter-spacing:.13em;color:#6c6c72}.title{font-size:31px;font-weight:800;margin:5px 0}.sub,.muted{color:#6c6c72;font-size:13px;line-height:1.45}.toolbar,.summary,.stageRail,.taskGrid,.devGrid{display:grid;gap:10px}.toolbar{display:flex;flex-wrap:wrap;margin:18px 0}.btn{border:1px solid #1d1d20;background:#fff;color:#171719;padding:10px 13px;border-radius:10px;font-weight:750;cursor:pointer}.btn.primary{background:#171719;color:#fff}.btn.danger{border-color:#a12d2d;color:#8a2727}.btn:disabled{opacity:.45;cursor:not-allowed}.summary{grid-template-columns:repeat(6,1fr)}.card,.stage,.panel,.task,.gate,.result{background:#fff;border:1px solid #e1e1e6;border-radius:14px}.card{padding:14px;min-height:92px}.label{font-size:11px;text-transform:uppercase;letter-spacing:.05em;color:#797981}.value{font-size:20px;font-weight:790;margin:7px 0}.stageRail{grid-template-columns:repeat(5,1fr);margin:14px 0}.stage{padding:13px;border-top:5px solid #9b9ba2}.stage[data-state="DONE"]{border-color:#34864a}.stage[data-state="OWNER_GATE"],.stage[data-state="BLOCKED_EXTERNAL"],.stage[data-state="BLOCKED_DATA"]{border-color:#c07922}.stageTitle{font-weight:780;margin:4px 0}.tabs{display:flex;gap:7px;overflow:auto;margin:17px 0 10px}.tab{white-space:nowrap;border:0;background:#e7e7eb;padding:9px 12px;border-radius:10px;font-weight:720;cursor:pointer}.tab.active{background:#171719;color:#fff}.view{display:none}.view.active{display:block}.panel{padding:16px;margin-bottom:12px}.sectionTitle{font-size:19px;font-weight:790;margin:0 0 10px}.taskGrid{grid-template-columns:repeat(2,1fr)}.task{padding:15px;cursor:pointer}.task.selected{outline:3px solid #607eab}.taskHead{display:flex;justify-content:space-between;gap:8px}.taskTitle{font-weight:780}.pill{display:inline-block;border-radius:999px;background:#ececf0;padding:4px 8px;font-size:10px;font-weight:800}.pill.DONE,.pill.LIVE_SITE_VERIFIED,.pill.ECONOMICALLY_PROVEN{background:#e2f6e7;color:#235c31}.pill.OWNER_GATE,.pill.BLOCKED_EXTERNAL,.pill.BLOCKED_DATA{background:#fff0d8;color:#734e10}.pill.CONFLICT,.pill.STALE{background:#ffe6e6;color:#832424}.detailGrid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:12px}.detail{background:#f6f6f8;border-radius:9px;padding:9px;font-size:12px}.detail b{display:block;margin-bottom:3px}.stageRows,.historyRows{display:grid;gap:8px}.row{display:grid;grid-template-columns:1.1fr .8fr 1fr 1.5fr;gap:10px;border-bottom:1px solid #eee;padding:10px 0;font-size:13px}.row:last-child{border:0}.controlsNote{padding:10px;border-left:4px solid #c07922;background:#fff8eb;font-size:13px}.route{padding:9px;border:1px solid #ccc;border-radius:9px;background:#fff}.gate{padding:15px;margin-bottom:9px}.gateButtons{display:flex;gap:7px;margin-top:10px}.devGrid{grid-template-columns:repeat(4,1fr)}pre{white-space:pre-wrap;word-break:break-word;background:#151519;color:#ededf0;border-radius:10px;padding:12px;max-height:360px;overflow:auto}.hidden{display:none}.notice{position:sticky;bottom:12px;margin-top:12px;padding:12px;background:#171719;color:#fff;border-radius:11px;display:none}.notice.show{display:block}details{margin-top:12px}a{color:#305f9b}@media(max-width:1050px){.summary{grid-template-columns:repeat(3,1fr)}.stageRail{grid-template-columns:1fr 1fr}.taskGrid{grid-template-columns:1fr}.devGrid{grid-template-columns:1fr 1fr}}@media(max-width:620px){.wrap{padding:14px}.summary,.stageRail,.detailGrid,.devGrid{grid-template-columns:1fr}.row{grid-template-columns:1fr}.title{font-size:25px}}
</style></head><body><div class="wrap">
<div class="top"><div><div class="eyebrow">DILIVOX · PROFIT ENGINE</div><div class="title">DILIVOX — Управление проектом</div><div class="sub">GitHub остаётся durable source of truth; обычная работа, статусы и bounded controls доступны здесь.</div></div><a class="btn" href="/profit">Пульт прибыли</a></div>
<div class="toolbar">
 <button class="btn primary" id="refresh">Обновить truth</button><button class="btn primary" id="startSelected">Запустить выбранную</button><button class="btn" id="startNext">Запустить следующую</button><button class="btn" id="startPackage">Запустить пакет 1–5</button>
 <button class="btn" id="pause">Пауза</button><button class="btn" id="resume">Продолжить</button><button class="btn danger" id="stop">Стоп</button>
 <select class="route" id="route"><option value="AUTO">AUTO / QUALITY-FIRST</option><option value="G2">G2 / Terra (только вверх)</option><option value="G3">G3 / Sol (только вверх)</option></select>
</div>
<div class="controlsNote">Astra не выбирается автоматически. Provider writes и Tilda publication недоступны; no automatic merge, no automatic deploy.</div>
<div class="summary">
 <div class="card"><div class="label">М milestone / этап</div><div class="value" id="milestone">—</div><div class="muted" id="stage">—</div></div>
 <div class="card"><div class="label">Задачи</div><div class="value"><span id="complete">—</span> / <span id="required">—</span></div><div class="muted">объективный denominator projection</div></div>
 <div class="card"><div class="label">Critical / Owner Gates</div><div class="value"><span id="blockers">—</span> / <span id="gates">—</span></div><div class="muted">blockers / approvals</div></div>
 <div class="card"><div class="label">Текущая работа</div><div class="value" id="currentTask">Нет</div><div class="muted" id="runState">IDLE</div></div>
 <div class="card"><div class="label">DEV_AI_COST / остаток</div><div class="value"><span id="devSpent">$0.00</span></div><div class="muted">остаток <b id="devRemaining">$10.00</b> · reserved <b id="reserved">—</b></div></div>
 <div class="card"><div class="label">Truth / SHA</div><div class="value"><span class="pill" id="truth">—</span></div><div class="muted" id="sha">—</div></div>
</div>
<div class="stageRail" id="stageRail"></div>
<div class="tabs" id="tabs">
 <button class="tab active" data-view="critical">Критический путь</button><button class="tab" data-view="whole">Весь проект</button><button class="tab" data-view="adaptive">Adaptive Funnel</button><button class="tab" data-view="content">Контент</button><button class="tab" data-view="providers">Провайдеры и compliance</button><button class="tab" data-view="owner">Owner Gates</button><button class="tab" data-view="development">Разработка</button><button class="tab" data-view="history">История</button>
</div>
<section class="view active" id="view-critical"><div class="panel"><div class="sectionTitle">Критический путь</div><div class="muted">Только dependency-ordered работа, которая двигает или блокирует следующий milestone.</div><div class="taskGrid" id="criticalTasks"></div></div></section>
<section class="view" id="view-whole"><div class="panel"><div class="sectionTitle">Весь проект</div><input class="route" id="search" placeholder="Поиск задачи"><div class="taskGrid" id="allTasks"></div></div><div class="panel hidden" id="taskDetail"></div></section>
<section class="view" id="view-adaptive"><div class="panel"><div class="sectionTitle">Adaptive Funnel AF-0…AF-4</div><div class="stageRows" id="adaptiveRows"></div></div></section>
<section class="view" id="view-content"><div class="panel"><div class="sectionTitle">Контент и economic gates</div><div class="detailGrid" id="contentGrid"></div></div></section>
<section class="view" id="view-providers"><div class="panel"><div class="sectionTitle">Провайдеры и соответствие</div><div class="detailGrid" id="providerGrid"></div></div></section>
<section class="view" id="view-owner"><div class="panel"><div class="sectionTitle">Только реальные Owner Gates</div><div id="ownerGates"></div></div></section>
<section class="view" id="view-development"><div class="panel"><div class="sectionTitle">Development execution / FinOps</div><div class="devGrid" id="devGrid"></div><div class="result" id="result" style="padding:14px;margin-top:12px"></div><details><summary>Диагностика / evidence</summary><pre id="diagnostics">—</pre></details></div></section>
<section class="view" id="view-history"><div class="panel"><div class="sectionTitle">Принятая история не исчезает</div><div class="historyRows" id="historyRows"></div></div></section>
<div class="notice" id="notice"></div>
</div><script>
const csrf=document.querySelector('meta[name="pe-csrf"]').content;let snapshot=null;let selectedTask=null;const packageTasks=new Set();
function esc(x){return String(x??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function money(x){let n=Number(x);return Number.isFinite(n)?'$'+n.toFixed(2):'—'}
function requestId(prefix){return prefix+'-'+crypto.randomUUID()}
function notice(text,bad=false){let n=document.getElementById('notice');n.textContent=text;n.style.background=bad?'#8a2727':'#171719';n.classList.add('show');setTimeout(()=>n.classList.remove('show'),6000)}
async function api(path,method='GET',body=null){let options={method,headers:{'Accept':'application/json'}};if(method==='POST'){options.headers['Content-Type']='application/json';options.headers['X-Profit-Engine-CSRF']=csrf;options.body=JSON.stringify(body||{})}let r=await fetch(path,options);let data=await r.json();if(!r.ok)throw new Error((data.code?data.code+': ':'')+(data.detail||data.error||'Ошибка'));return data}
function pill(state){return `<span class="pill ${esc(state)}">${esc(state)}</span>`}
function taskCard(t,packageMode=false){let checked=packageTasks.has(t.task_id)?'checked':'';return `<article class="task ${selectedTask===t.task_id?'selected':''}" data-task="${esc(t.task_id)}"><div class="taskHead"><div><div class="taskTitle">${esc(t.title_ru)}</div><div class="muted">${esc(t.task_id)}</div></div>${pill(t.status)}</div><p>${esc(t.outcome_ru)}</p><div class="muted">Этап ${esc(t.stage)} · ${esc(t.workstream)} · target ${esc(t.target_state)}</div>${packageMode?`<label><input type="checkbox" data-package="${esc(t.task_id)}" ${checked}> В пакет</label>`:''}</article>`}
function bindTasks(){document.querySelectorAll('[data-task]').forEach(el=>el.onclick=e=>{if(e.target.matches('[data-package]'))return;selectedTask=el.dataset.task;renderTasks();showTask(selectedTask)});document.querySelectorAll('[data-package]').forEach(el=>el.onchange=()=>{if(el.checked){if(packageTasks.size>=5){el.checked=false;notice('Пакет ограничен пятью задачами.',true);return}packageTasks.add(el.dataset.package)}else packageTasks.delete(el.dataset.package)})}
function renderTasks(){document.getElementById('criticalTasks').innerHTML=(snapshot.critical_path||[]).map(t=>taskCard(t)).join('')||'<p>Критический путь закрыт.</p>';let q=document.getElementById('search').value.toLowerCase();let tasks=(snapshot.tasks||[]).filter(t=>!q||JSON.stringify([t.task_id,t.title_ru,t.outcome_ru,t.workstream]).toLowerCase().includes(q));document.getElementById('allTasks').innerHTML=tasks.map(t=>taskCard(t,true)).join('');bindTasks()}
function detail(label,value){return `<div class="detail"><b>${esc(label)}</b>${esc(value)}</div>`}
function showTask(id){let t=(snapshot.tasks||[]).find(x=>x.task_id===id);if(!t)return;let d=document.getElementById('taskDetail');d.classList.remove('hidden');d.innerHTML=`<div class="sectionTitle">${esc(t.title_ru)}</div><p>${esc(t.outcome_ru)}</p><div class="detailGrid">${detail('task_id',t.task_id)}${detail('Статус / target',t.status+' → '+t.target_state)}${detail('Этап / workstream',t.stage+' / '+t.workstream)}${detail('Dependencies',(t.dependencies||[]).join(', ')||'нет')}${detail('Blockers',(t.blockers||[]).join(' · ')||'нет')}${detail('Owner Gate',t.owner_gate?'ДА':'нет')}${detail('Executor',t.executor)}${detail('Route / model',t.execution_route+' / '+t.model)}${detail('Routing reason',t.routing_reason)}${detail('Why not cheaper',t.why_not_cheaper||'не требуется')}${detail('Quality / hard cap',t.quality_floor+' / '+money(t.hard_cap_usd))}${detail('Actual cost',money(t.actual_cost_usd))}${detail('Branch / PR',String(t.branch||'—')+' / '+String(t.pr||'—'))}${detail('SHA / CI',String(t.sha||'—')+' / '+t.ci_state)}${detail('Live provider / site',t.live_provider_state+' / '+t.live_site_state)}${detail('Economic',t.economic_state)}${detail('Сейчас',t.current_action||'—')}${detail('Дальше',t.next_action||'—')}${detail('Evidence time',t.last_evidence_time||'—')}</div><details><summary>Technical evidence refs</summary><pre>${esc((t.evidence_refs||[]).join('\n')||t.source_ref||'нет')}</pre></details>`}
function render(s){snapshot=s;document.getElementById('milestone').textContent=s.current_milestone;document.getElementById('stage').textContent='Этап '+s.current_stage;document.getElementById('complete').textContent=s.completed_tasks;document.getElementById('required').textContent=s.required_tasks;document.getElementById('blockers').textContent=s.critical_blocker_count;document.getElementById('gates').textContent=s.owner_gate_count;let d=s.development||{},c=d.controller||{},a=c.active||{};document.getElementById('currentTask').textContent=d.current_task||'Нет';document.getElementById('runState').textContent=(d.execution_route||'—')+' · '+(d.model||'—')+' · '+(d.run_state||'IDLE');document.getElementById('devSpent').textContent=money(d.dev_ai_cost_usd);document.getElementById('devRemaining').textContent=money(d.remaining_dev_envelope_usd);document.getElementById('reserved').textContent=money(d.reserved_maximum_usd);let truth=document.getElementById('truth');truth.textContent=s.truth_state;truth.className='pill '+s.truth_state;document.getElementById('sha').textContent=(s.canonical_profit_engine_sha||'—').slice(0,12);document.getElementById('stageRail').innerHTML=(s.stages||[]).map(x=>`<div class="stage" data-state="${esc(x.status)}"><div class="label">Этап ${esc(x.stage_id)}</div><div class="stageTitle">${esc(x.title_ru)}</div>${pill(x.status)}<div class="muted">${x.completed_tasks}/${x.required_tasks} · blockers ${x.blocker_count} · gates ${x.owner_gate_count}</div><div class="muted">${esc(x.next_milestone_ru)}</div></div>`).join('');renderTasks();document.getElementById('adaptiveRows').innerHTML=(s.adaptive_funnel.packages||[]).map(x=>`<div class="row"><b>${esc(x.package)}</b><span>${pill(x.state)}</span><span>${esc(x.policy)}</span><span>fallback ${esc(x.fallback)} · ROI ${esc(x.feature_roi)}</span></div>`).join('');document.getElementById('contentGrid').innerHTML=Object.entries(s.content||{}).map(([k,v])=>detail(k,v)).join('');document.getElementById('providerGrid').innerHTML=Object.entries(s.providers_compliance||{}).map(([k,v])=>detail(k,v)).join('');document.getElementById('ownerGates').innerHTML=(s.owner_gates||[]).map(t=>`<div class="gate"><div class="taskHead"><b>${esc(t.title_ru)}</b>${pill(t.status)}</div><p><b>Почему:</b> ${esc((t.blockers||[]).join(' · '))}</p><p><b>Exact scope:</b> ${esc(t.owner_gate_id)} · ${esc(t.owner_gate_scope_digest)}</p><p><b>Что изменится:</b> разрешение фиксирует только этот scope и SHA; provider action автоматически не выполняется.</p><div class="gateButtons"><button class="btn" data-gate="APPROVE" data-id="${esc(t.owner_gate_id)}">APPROVE</button><button class="btn danger" data-gate="REJECT" data-id="${esc(t.owner_gate_id)}">REJECT</button><button class="btn" data-gate="DEFER" data-id="${esc(t.owner_gate_id)}">DEFER</button></div></div>`).join('')||'<p>Owner Gates отсутствуют.</p>';document.querySelectorAll('[data-gate]').forEach(b=>b.onclick=()=>ownerDecision(b.dataset.id,b.dataset.gate));document.getElementById('historyRows').innerHTML=(s.history||[]).map(t=>`<div class="row"><b>${esc(t.title_ru)}</b><span>${pill(t.status)}</span><span>${esc(t.task_id)}</span><span>${esc((t.evidence_refs||[]).join(' · ')||t.source_ref||'accepted history')}</span></div>`).join('');let devFields={run_state:d.run_state,current_task:d.current_task,current_package:(d.current_package||[]).join(' → '),execution_route:d.execution_route,model:d.model,quality_floor:a.quality_floor,routing_reason:a.routing_reason,why_not_cheaper:a.why_not_cheaper,reserved_maximum_usd:d.reserved_maximum_usd,actual_cost_usd:d.actual_cost_usd,dev_ai_cost_usd:d.dev_ai_cost_usd,remaining_dev_envelope_usd:d.remaining_dev_envelope_usd,warning_80_percent:d.warning_80_percent,astra_enabled:d.astra_enabled,latest_completed_action:a.latest_completed_action,current_action:a.current_action,automatic_retry_count:a.automatic_retry_count};document.getElementById('devGrid').innerHTML=Object.entries(devFields).map(([k,v])=>detail(k,v)).join('');document.getElementById('result').innerHTML='<b>Последний результат</b><pre>'+esc(JSON.stringify(c.last_result||{state:'NO_RESULT'},null,2))+'</pre>';document.getElementById('diagnostics').textContent=JSON.stringify({github_control_state:s.github_control_state,ci:s.ci,controller:c,provider_write_allowed:s.provider_write_allowed,auto_merge:s.auto_merge,auto_deploy:s.auto_deploy},null,2);let activeId=a.package_id||a.request_id;document.getElementById('pause').disabled=!activeId||c.state!=='RUNNING';document.getElementById('resume').disabled=!activeId||c.state!=='PAUSED';document.getElementById('stop').disabled=!activeId||!['RUNNING','PAUSE_REQUESTED','PAUSED'].includes(c.state)}
async function load(remote=false){try{let p=remote?'/api/project/refresh':'/api/project/snapshot';let s=remote?await api(p,'POST',{request_id:requestId('refresh')}):await api(p);render(s)}catch(e){notice(e.message,true)}}
async function start(id){if(!id){notice('Сначала выбери задачу.',true);return}try{let r=await api('/api/development/start','POST',{request_id:requestId('start'),task_id:id,route_override:document.getElementById('route').value});notice('Запуск принят: '+r.state);await load(true)}catch(e){notice(e.message,true)}}
const CONTROL_ENDPOINTS={pause:'/api/development/pause',resume:'/api/development/resume',stop:'/api/development/stop'};
async function control(kind){let endpoint=CONTROL_ENDPOINTS[kind],a=((snapshot.development||{}).controller||{}).active||{},activeId=a.package_id||a.request_id;if(!endpoint){notice('Команда не входит в allowlist.',true);return}if(!activeId){notice('Нет exact active package.',true);return}try{let r=await api(endpoint,'POST',{request_id:requestId(kind),active_id:activeId});notice(r.state);await load(true)}catch(e){notice(e.message,true)}}
async function ownerDecision(gate,decision){try{let r=await api('/api/owner-gates/'+encodeURIComponent(gate)+'/decision','POST',{request_id:requestId('gate'),decision,evidence_note:'Owner decision from local Project Control'});notice(r.state+': '+r.decision);await load(true)}catch(e){notice(e.message,true)}}
document.getElementById('refresh').onclick=()=>load(true);document.getElementById('startSelected').onclick=()=>start(selectedTask);document.getElementById('startNext').onclick=()=>start((snapshot.critical_path||[])[0]?.task_id);document.getElementById('startPackage').onclick=async()=>{let ids=[...packageTasks];if(!ids.length){notice('Выбери 1–5 задач флажками.',true);return}try{let r=await api('/api/development/package/start','POST',{request_id:requestId('package'),task_ids:ids,route_override:document.getElementById('route').value});notice(r.state);await load(true)}catch(e){notice(e.message,true)}};document.getElementById('pause').onclick=()=>control('pause');document.getElementById('resume').onclick=()=>control('resume');document.getElementById('stop').onclick=()=>control('stop');document.getElementById('search').oninput=renderTasks;document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById('view-'+b.dataset.view).classList.add('active')});load(true);setInterval(()=>load(false),15000);
</script></body></html>'''


def render_project_html(csrf_token: str) -> str:
    if not csrf_token or "<" in csrf_token or '"' in csrf_token:
        raise ValueError("invalid per-launch CSRF token")
    return PROJECT_HTML.replace("__CSRF_TOKEN__", csrf_token)
